-- Cupons promocionais do plano PRO.
-- Aplicada no projeto Supabase mixlupweuzshctnldeyl.
CREATE TABLE IF NOT EXISTS public."subscriptionCoupons" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(80) NOT NULL UNIQUE,
  "description" varchar(240) NOT NULL DEFAULT '',
  "discountType" varchar(16) NOT NULL DEFAULT 'percent' CHECK ("discountType" IN ('percent', 'fixed')),
  "discountValue" double precision NOT NULL DEFAULT 0 CHECK ("discountValue" >= 0),
  "durationDays" integer NOT NULL DEFAULT 1 CHECK ("durationDays" > 0),
  "validUntil" timestamp NULL,
  "assignedUserId" integer NULL,
  "isActive" boolean NOT NULL DEFAULT true,
  "revokedAt" timestamp NULL,
  "createdByUserId" integer NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS public."subscriptionCouponRedemptions" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "couponId" integer NOT NULL REFERENCES public."subscriptionCoupons"("id") ON DELETE CASCADE,
  "userId" integer NOT NULL REFERENCES public."users"("id") ON DELETE CASCADE,
  "status" varchar(16) NOT NULL DEFAULT 'pending' CHECK ("status" IN ('pending', 'applied', 'revoked')),
  "discountAmount" double precision NOT NULL DEFAULT 0,
  "paymentId" integer NULL,
  "redeemedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "expiresAt" timestamp NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE ("couponId", "userId")
);
ALTER TABLE public."mercadoPagoPixPayments" ADD COLUMN IF NOT EXISTS "couponId" integer NULL REFERENCES public."subscriptionCoupons"("id") ON DELETE SET NULL;
ALTER TABLE public."mercadoPagoPixPayments" ADD COLUMN IF NOT EXISTS "couponRedemptionId" integer NULL REFERENCES public."subscriptionCouponRedemptions"("id") ON DELETE SET NULL;
